<?php
declare(strict_types=1);
require dirname(__DIR__, 2) . '/seafort/app/bootstrap.php';
require_once dirname(__DIR__, 2) . '/seafort/app/collections.php';
sf_admin_session();
if (empty($_SESSION['authenticated'])) { header('Location: /admin/', true, 303); exit; }
$type = is_string($_GET['type'] ?? null) ? $_GET['type'] : 'projects';
if ($type === 'team') { http_response_code(404); exit('Bu bölüm kaldırıldı.'); }
try { sf_collection_file($type); } catch (InvalidArgumentException) { http_response_code(404); exit('Bölüm bulunamadı.'); }
$meta = [
    'projects' => ['title'=>'Projeler','singular'=>'Proje','new'=>'Yeni proje','heading'=>'Yaptığınız işi açıkça anlatın.','intro'=>'Proje görsellerini, kapsamını ve doğrulanmış bilgilerini tek yerden yönetin.','path'=>'/projects/','empty'=>'Henüz proje eklenmedi.'],
    'team' => ['title'=>'Ekip','singular'=>'Çalışan','new'=>'Çalışan ekle','heading'=>'Ekibinizle doğrudan bağlantı.','intro'=>'Çalışanları departmanlarına göre düzenleyin; fotoğraf, ad soyad, görev, e-posta ve telefon bilgilerini yönetin.','path'=>'/team/','empty'=>'Henüz çalışan eklenmedi.'],
    'slides' => ['title'=>'Ana sayfa sliderı','singular'=>'Slayt','new'=>'Slayt ekle','heading'=>'İlk ekranda doğru mesaj.','intro'=>'Ana başlıkları, görselleri ve yönlendirmeleri sıralı biçimde düzenleyin.','path'=>'/','empty'=>'Henüz slayt eklenmedi.'],
][$type];
$base = '/admin/manage.php?type=' . $type;
$error='';$notice='';$item=null;$draftInput=null;
$editId=is_string($_GET['edit'] ?? null)?$_GET['edit']:null;$isNew=isset($_GET['new']);
$revision=null;
function collection_admin_redirect(string $base, array $extra=[]): never { header('Location: '.$base.($extra?'&'.http_build_query($extra):''),true,303);exit; }
if (($_SERVER['REQUEST_METHOD'] ?? '')==='POST') {
    try {
        sf_require_csrf();
        $action=is_string($_POST['action'] ?? null)?$_POST['action']:'';
        if ($action==='logout') {sf_logout();header('Location: /admin/',true,303);exit;}
        if ($action==='export') {
            header('Content-Type: application/json; charset=utf-8');header('Content-Disposition: attachment; filename="seafort-'.$type.'-'.gmdate('Y-m-d').'.json"');
            echo json_encode(['version'=>1,'exported_at'=>sf_now(),'items'=>sf_collection($type,false)],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR);exit;
        }
        $id=is_string($_POST['id'] ?? null)&&$_POST['id']!==''?$_POST['id']:null;
        if ($action==='save') {
            $keys=match($type){'team'=>['name','role','department','email','phone','photo'],'projects'=>array_merge(['title','slug','summary','body','category','location','year','cover','cover_alt'],sf_project_case_fields()),'slides'=>['title','description','eyebrow','cover','cover_alt','link_label','link_href']};
            $draftInput=[];foreach(array_merge($keys,['status','order']) as $key){$draftInput[$key]=is_string($_POST[$key]??null)?$_POST[$key]:'';}
            if ($type==='projects') {
                if (isset($_POST['gallery'])&&!is_array($_POST['gallery'])) throw new InvalidArgumentException('Galeri bilgileri geçersiz.');
                $draftInput['gallery']=$_POST['gallery']??[];
            }
            $editId=$id;$isNew=$id===null;$revision=is_string($_POST['revision']??null)?$_POST['revision']:'';
            $check=$draftInput;$check['status']='draft';sf_collection_validate($type,$check);
            $imageKey=$type==='team'?'photo':'cover';
            if (isset($_FILES['image_upload'])&&($_FILES['image_upload']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE) $draftInput[$imageKey]=sf_store_upload($_FILES['image_upload']);
            if (($_POST['remove_image']??'')==='1') $draftInput[$imageKey]='';
            if ($type==='projects') {
                for ($galleryIndex=0;$galleryIndex<6;$galleryIndex++) {
                    $draftInput['gallery'][$galleryIndex]??=['image'=>'','caption'=>'','stage'=>''];
                    if (($_POST['gallery_remove_'.$galleryIndex]??'')==='1') $draftInput['gallery'][$galleryIndex]['image']='';
                    $uploadKey='gallery_upload_'.$galleryIndex;
                    if (isset($_FILES[$uploadKey])&&($_FILES[$uploadKey]['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE) $draftInput['gallery'][$galleryIndex]['image']=sf_store_upload($_FILES[$uploadKey]);
                }
            }
            $saved=sf_collection_save($type,$draftInput,$id,$id!==null?$revision:null);
            $_SESSION['collection_notice']=$draftInput['status']==='published'?'Kayıt yayımlandı. Sitede görüntülenebilir.':'Taslak kaydedildi. Ziyaretçilere gösterilmez.';
            collection_admin_redirect($base,['edit'=>$saved]);
        }
        if ($id!==null&&in_array($action,['archive','restore','unpublish'],true)) {
            sf_collection_status($type,$id,$action);$_SESSION['collection_notice']=$action==='archive'?'Kayıt arşive taşındı. Kalıcı olarak silinmedi.':($action==='restore'?'Kayıt taslak olarak geri alındı.':'Kayıt yayından kaldırılıp taslağa alındı.');collection_admin_redirect($base);
        }
        throw new InvalidArgumentException('İşlem tanınmadı.');
    } catch(InvalidArgumentException $exception){$error=$exception->getMessage();}
    catch(Throwable $exception){error_log('Seafort collections: '.$exception->getMessage());$error='İşlem tamamlanamadı. Sunucu kayıtlarını ve dosya izinlerini kontrol edin.';}
}
if(isset($_SESSION['collection_notice'])){$notice=(string)$_SESSION['collection_notice'];unset($_SESSION['collection_notice']);}
$items=sf_collection($type,false);$counts=['all'=>0,'published'=>0,'draft'=>0,'archived'=>0];
foreach($items as $entry){$state=$entry['status']??'draft';if(isset($counts[$state]))$counts[$state]++;if($state!=='archived')$counts['all']++;}
if($editId!==null){$item=sf_collection_item($type,$editId,false);if(!$item||($item['status']??'')==='archived'){$error='Kayıt bulunamadı veya arşivde. Önce arşiv listesinden taslak olarak geri alın.';$item=null;$editId=null;}}
if($isNew){$item=['id'=>'','status'=>'draft','order'=>min(999,($counts['all']+1)*10)];if($type==='projects')$item['case_schema']='1';}
if($draftInput!==null)$item=array_merge($item??[],$draftInput,['id'=>$editId??'']);
$filter=is_string($_GET['status']??null)&&in_array($_GET['status'],['published','draft','archived'],true)?$_GET['status']:'all';
$search=is_string($_GET['q']??null)?trim($_GET['q']):'';
$labels=['published'=>'Yayında','draft'=>'Taslak','archived'=>'Arşiv'];
$imageKey=$type==='team'?'photo':'cover';
$previewProject=null;
if ($type==='projects'&&isset($_GET['preview'])) {
    $previewId=is_string($_GET['preview'])?$_GET['preview']:'';
    $previewProject=sf_collection_item('projects',$previewId,false);
    if (!$previewProject||($previewProject['status']??'')==='archived') {$previewProject=null;$error='Önizlenecek kayıt bulunamadı veya arşivde.';}
}
